import { useState } from "react";

export function App() {
  const [terms, setTerms] = useState(false);
  const [status, setStatus] = useState("idle");
  return (
    <div>
      <label><input data-testid="terms" type="checkbox" checked={terms} onChange={(event) => setTerms(event.target.checked)} /> Accept terms</label>
      <button data-testid="terms-submit" onClick={() => setStatus(terms ? "Accepted" : "Needs terms")}>Accept terms</button>
      <span data-testid="terms-status">{status}</span>
    </div>
  );
}
